CREATE TABLE users (id TEXT PRIMARY KEY NOT NULL, name TEXT NOT NULL CHECK(length(name)>0), normalized_name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE semesters (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK(length(name)>0), normalized_name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,normalized_name), UNIQUE(id,user_id));
CREATE TABLE subjects (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL, semester_id TEXT NOT NULL, name TEXT NOT NULL CHECK(length(name)>0), normalized_name TEXT NOT NULL, full_score_minor INTEGER NOT NULL CHECK(full_score_minor>0 AND full_score_minor<=1000000000), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,semester_id,normalized_name), UNIQUE(id,user_id,semester_id), FOREIGN KEY(semester_id,user_id) REFERENCES semesters(id,user_id) ON DELETE CASCADE);
CREATE TABLE assets (id TEXT PRIMARY KEY NOT NULL, relative_path TEXT NOT NULL UNIQUE, mime_type TEXT NOT NULL, sha256 TEXT NOT NULL, byte_count INTEGER NOT NULL CHECK(byte_count>=0));
CREATE TABLE exam_records (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL, semester_id TEXT NOT NULL, subject_id TEXT NOT NULL, exam_name TEXT NOT NULL, normalized_exam_name TEXT NOT NULL, exam_date TEXT NOT NULL, score_minor INTEGER NOT NULL CHECK(score_minor>=0 AND score_minor<=1000000000), exam_type TEXT NOT NULL CHECK(exam_type IN ('monthly','midterm','final','other')), class_rank INTEGER CHECK(class_rank>0), grade_rank INTEGER CHECK(grade_rank>0), district_rank INTEGER CHECK(district_rank>0), reflection TEXT, attachment_id TEXT REFERENCES assets(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(subject_id,user_id,semester_id) REFERENCES subjects(id,user_id,semester_id) ON DELETE CASCADE, UNIQUE(user_id,semester_id,subject_id,normalized_exam_name,exam_date,score_minor));
CREATE INDEX exams_scope_date ON exam_records(user_id,semester_id,exam_date DESC,created_at DESC,id DESC);
CREATE INDEX exams_subject_date ON exam_records(subject_id,exam_date,id);
CREATE TRIGGER exam_score_insert BEFORE INSERT ON exam_records WHEN NEW.score_minor > (SELECT full_score_minor FROM subjects WHERE id=NEW.subject_id) BEGIN SELECT RAISE(ABORT,'score exceeds full score'); END;
CREATE TRIGGER exam_score_update BEFORE UPDATE ON exam_records WHEN NEW.score_minor > (SELECT full_score_minor FROM subjects WHERE id=NEW.subject_id) BEGIN SELECT RAISE(ABORT,'score exceeds full score'); END;
CREATE TRIGGER subject_full_score_update BEFORE UPDATE OF full_score_minor ON subjects WHEN NEW.full_score_minor < (SELECT MAX(score_minor) FROM exam_records WHERE subject_id=OLD.id) BEGIN SELECT RAISE(ABORT,'full score below historical score'); END;
CREATE TABLE legacy_id_map (source_dataset_id TEXT NOT NULL, entity_type TEXT NOT NULL, legacy_id TEXT NOT NULL, canonical_id TEXT NOT NULL, PRIMARY KEY(source_dataset_id,entity_type,legacy_id));
CREATE TABLE app_metadata (key TEXT PRIMARY KEY NOT NULL, value TEXT NOT NULL);
CREATE TABLE preferences_state (singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1), revision INTEGER NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE restore_operations (operation_id TEXT PRIMARY KEY NOT NULL, backup_id TEXT NOT NULL, phase TEXT NOT NULL, target_preferences_json TEXT NOT NULL, committed_at TEXT NOT NULL);
CREATE TABLE drafts (key TEXT PRIMARY KEY NOT NULL, payload BLOB NOT NULL);
